import click
from click.testing import CliRunner


def test_probe():
    @click.command()
    @click.option('--a', is_flag=True, flag_value=False, default=True)
    @click.option('--m', 'm', flag_value='x', default=True)
    def cli(a, m):
        click.echo(f'{a!r} {m!r}')

    ctx = click.Context(cli)
    opts = {p.name: p for p in cli.params}
    assert opts['a'].get_default(ctx) is True
    assert opts['m'].get_default(ctx) == 'x'
    r = CliRunner().invoke(cli, [])
    assert r.output.strip() == "True 'x'"
    r = CliRunner().invoke(cli, ['--a'])
    assert r.output.strip().startswith('False')

