import click
from click import Context


def _get(opt):
    cmd = click.Command('c', params=[opt])
    ctx = Context(cmd)
    return opt.get_default(ctx)


def test_bool_flag_default_true_literal():
    o = click.Option(['--foo'], is_flag=True, flag_value=False, default=True)
    assert o.is_bool_flag
    assert _get(o) is True


def test_nonbool_still_substituted():
    o = click.Option(['--foo'], flag_value='upper', default=True)
    assert not o.is_bool_flag
    assert _get(o) == 'upper'


def test_callable_flag_value_class():
    class K:
        pass
    o = click.Option(['--foo'], flag_value=K, default=True)
    assert _get(o) is K


def test_invoke_negative_flag():
    from click.testing import CliRunner

    @click.command()
    @click.option('--foo', is_flag=True, flag_value=False, default=True)
    def cli(foo):
        click.echo(repr(foo), nl=False)

    r = CliRunner()
    assert r.invoke(cli, []).output == 'True'
    assert r.invoke(cli, ['--foo']).output == 'False'

