import click
from click.testing import CliRunner


def _run(args, **kw):
    @click.command()
    @click.option('--foo', **kw)
    def cli(foo):
        click.echo(repr(foo), nl=False)
    return CliRunner().invoke(cli, args)


def test_neg_bool_flag_default_true():
    r = _run([], is_flag=True, default=True, flag_value=False)
    assert r.output == 'True'
    r = _run(['--foo'], is_flag=True, default=True, flag_value=False)
    assert r.output == 'False'


def test_non_bool_flag_sentinel_still_works():
    r = _run([], default=True, flag_value='upper')
    assert r.output == "'upper'"
    r = _run([], is_flag=True, default=True, flag_value=3)
    assert r.output == '3'


def test_callable_flag_value_not_called():
    class K:
        pass
    @click.command()
    @click.option('--foo', default=True, flag_value=K)
    def cli(foo):
        click.echo(str(foo is K), nl=False)
    r = CliRunner().invoke(cli, [])
    assert r.output == 'True'

