import click, pathlib, enum
from click.testing import CliRunner

class E(enum.Enum):
    A = 1
    B = 2

def test_probe():
    @click.command()
    @click.option('--a', 'x', flag_value=E.A)
    @click.option('--b', 'x', flag_value=E.B)
    def cli(x):
        click.echo(repr(x), nl=False)
    r = CliRunner()
    assert r.invoke(cli, []).output == 'None'
    assert r.invoke(cli, ['--b']).output == repr(E.B)

    @click.command()
    @click.option('--p', flag_value=pathlib.Path('/x'))
    def cli2(p):
        click.echo(repr(p), nl=False)
    assert r.invoke(cli2, ['--p']).output == repr(pathlib.Path('/x'))
    assert r.invoke(cli2, []).output in ('None', 'False')
    assert click.Option(['--q'], flag_value=None).type is not click.UNPROCESSED
    assert click.Option(['--q'], flag_value='s').type is click.STRING

